#include <iostream>
#include <algorithm>
#include <cstdint>
using namespace std;

constexpr int64_t BASE = 1000000007LL;

int64_t findvalue(int64_t i, int64_t j) {
    if (i > j) swap(i, j);

    if (i == 1) return j;
    if (i == j) return 1;
    if (j == i + 1 && i % 2 == 1) return 2;

    int64_t delta = (j % 4 == 1 || j % 4 == 2) ? 2 : -2;

    if (i % 2 == 1)
        return j + ((i - 1) / 2) * delta;

    int64_t result = (j % 2 == 0) ? j - 1 : j + 1;
    return result + ((i - 2) / 2) * delta;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int q;
    cin >> q;

    while (q--) {
        int64_t x1, y1, x2, y2, K;
        cin >> x1 >> y1 >> x2 >> y2 >> K;

        int64_t ans = 0;
        for (int64_t j = x1; j <= x2; ++j) {
            for (int64_t k = y1; k <= y2; ++k) {
                int64_t temp = findvalue(j, k);
                if (temp <= K)
                    ans = (ans + temp) % BASE;
            }
        }

        cout << ans << '\n';
    }

    return 0;
}

